import os
from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_PARAGRAPH_ALIGNMENT
from docx.oxml.ns import qn

def create_manual():
    doc = Document()
    
    # Set default font to SimSun (宋体)
    style = doc.styles['Normal']
    font = style.font
    font.name = '宋体'
    font.size = Pt(12)
    style.element.rPr.rFonts.set(qn('w:eastAsia'), '宋体')

    def add_heading(text, level=1):
        h = doc.add_heading(text, level=level)
        for run in h.runs:
            run.font.name = '宋体'
            run.font.color.rgb = RGBColor(0, 0, 0)
            run._element.rPr.rFonts.set(qn('w:eastAsia'), '宋体')

    def add_para(text):
        p = doc.add_paragraph(text)
        p.paragraph_format.first_line_indent = Pt(24)
        for run in p.runs:
            run.font.name = '宋体'
            run._element.rPr.rFonts.set(qn('w:eastAsia'), '宋体')

    # Title
    title = doc.add_heading('AI短剧平台用户操作使用说明书', 0)
    title.alignment = WD_PARAGRAPH_ALIGNMENT.CENTER
    for run in title.runs:
        run.font.name = '宋体'
        run._element.rPr.rFonts.set(qn('w:eastAsia'), '宋体')

    doc.add_page_break()

    # Content Generation with extremely detailed descriptions to meet word count

    sections = [
        {
            "title": "1. 系统登录与身份验证",
            "content": [
                ("1.1 登录入口位置", "本平台的系统登录入口位于官方网站首页的右上角。用户在浏览器地址栏输入平台专属的官方网址后，系统会自动加载并呈现出设计精美、布局清晰的平台首页。在首页的右上角区域，有一个醒目的“登录/注册”按钮，该按钮采用了平台主题色进行高亮显示，以确保用户在第一时间能够发现。点击该按钮后，系统将通过平滑的过渡动画，在屏幕中央弹出一个极具现代感的登录弹窗，或者直接跳转至专属的全屏登录页面。登录页面左侧展示了平台的核心功能特性，如“AI编剧”、“主体固定”、“AI分镜”等，右侧则是完整的登录表单区域。这一设计不仅方便了用户的快速接入，同时也起到了良好的品牌宣传与功能展示作用。"),
                ("1.2 账号密码输入规则", "在登录表单中，系统要求用户输入已注册的有效账号与密码。账号输入框支持手机号码、注册邮箱或者自定义的平台用户名三种形式。当用户在账号输入框中键入信息时，系统会实时进行格式初步校验。例如，如果输入的是手机号码，系统会检查其是否符合11位数字的国内标准格式；如果是邮箱，则会检查是否包含“@”符号及正确的域名后缀。密码输入框则采用了安全隐藏机制，默认以星号或圆点替代用户输入的真实字符，以防止密码在公共环境下被旁人窥视。同时，密码输入框右侧配备了一个“眼睛”图标的切换按钮，用户可以点击该按钮，在“隐藏”与“显示”模式之间自由切换，以便在输入复杂的长密码时确认输入的准确性。为了保障账户安全，系统对密码的复杂度有严格要求，密码长度必须在8至20个字符之间，且必须同时包含大小写字母、数字以及特殊符号（如@、#、$、%等）。如果用户输入的密码不符合复杂度要求或长度限制，输入框下方会立即显示红色的错误提示信息。"),
                ("1.3 验证码获取与校验逻辑", "为了有效防止恶意机器人的自动化暴力破解和频繁的无效登录尝试，平台在登录流程中引入了智能图形验证码机制。在账号和密码输入框下方，设有一个专门的验证码输入区域。系统会在该区域右侧动态生成一张包含4到6位随机字母与数字组合的扭曲图形验证码，或者采用更为先进的滑动拼图验证码。用户需要准确识别图形中的字符并将其填入左侧的输入框中。如果验证码图片因扭曲过度难以辨认，用户可以直接点击验证码图片，系统会立即发起请求并刷新更换一张全新的验证码图片。在用户点击“立即登录”按钮时，系统前端会首先对验证码进行校验。只有当验证码输入完全正确，且未超过其5分钟的有效生命周期时，系统才会将包含账号、加密密码和验证码在内的完整登录请求发送至后端服务器进行进一步的身份核验。如果验证码错误，系统将阻断登录请求，并清空验证码输入框，提示用户重新输入。"),
                ("1.4 多维度身份核验流程", "当用户的登录请求抵达后端服务器后，系统将启动多维度、深层次的身份核验流程。首先，系统会在核心数据库的活跃用户表中检索匹配的账号信息。如果账号不存在或已被冻结、注销，系统将立即返回对应的拒绝登录状态码。确认账号存在且状态正常后，系统会提取数据库中存储的经过高强度加盐哈希（Salted Hash）处理的密码密文，与用户此次提交并经同样算法处理后的密码进行严格比对。在账号密码匹配成功的基础上，系统还会对用户的登录环境进行风险评估。系统会检测用户当前登录的IP地址、设备指纹、浏览器指纹等信息，并与该账号的历史常用登录环境进行比对。如果系统发现当前登录行为发生在异地，或者使用了全新的、未曾记录过的陌生设备，系统将触发安全风控机制的第二层核验——多因素认证（MFA）。此时，系统会暂停登录流程的直接放行，转而向用户绑定的安全手机号码发送一条包含6位数字的动态短信验证码，或者向绑定的安全邮箱发送一封包含验证链接的邮件。用户必须在规定的时效（通常为10分钟）内，正确输入短信验证码或点击邮件中的安全链接，才能最终完成整个身份核验流程并成功进入系统。这一多维度的核验机制最大程度地保障了用户资产和创作数据的绝对安全。"),
                ("1.5 登录失败各类异常场景的处理方案", "在用户的日常使用过程中，可能会遇到各种导致登录失败的异常场景。平台针对这些场景设计了详尽且人性化的处理方案及提示机制。场景一：账号或密码错误。当用户输入的密码与数据库记录不符时，系统不会明确告知是账号不存在还是密码错误，而是统一提示“账号或密码不正确，请重新输入”，这种模糊提示策略是为了防止恶意攻击者通过穷举法探测系统中存在的有效账号。场景二：连续多次密码错误。为了防止暴力破解，当同一账号在连续30分钟内累计输入错误密码达到5次时，系统将自动触发账号保护机制，暂时锁定该账号的登录权限，锁定时间通常为2小时。在锁定期间，即使输入正确的密码也无法登录，系统会明确提示“您的账号因连续多次输入错误密码已被暂时锁定，请2小时后再试，或通过找回密码功能解锁”。场景三：网络异常或服务器响应超时。当用户的网络环境极度不稳定或服务器正在进行紧急维护时，登录请求可能无法在预定时间内得到响应。此时，前端界面会显示加载中的动画，若超过15秒未收到服务器返回结果，系统将主动中断请求，并弹出友好的提示框“当前网络连接不稳定或服务器正忙，请检查您的网络设置后稍后再试”。场景四：验证码失效或错误。如前文所述，系统会明确用红色字体在验证码输入框下方提示“验证码已过期，请点击刷新”或“验证码输入错误，请重新输入”。"),
                ("1.6 忘记密码的全流程找回步骤", "对于遗忘密码的用户，平台提供了一条安全、便捷的自助密码找回通道。在登录页面的“立即登录”按钮下方，设有一个“忘记密码？”的文字链接。点击该链接后，用户将被引导至独立的“找回密码”流程页面。整个找回流程分为严谨的四个步骤。第一步：确认账号身份。用户需要在输入框中填写需要找回密码的注册手机号或电子邮箱，并完成一个图形验证码的拖拽或字符识别，以证明其为真实的人类操作。点击“下一步”后，系统会验证该账号的有效性。第二步：安全身份验证。系统会根据用户填写的账号类型，向对应的手机号或邮箱发送一条包含6位动态安全验证码的信息。页面会同步显示倒计时（通常为60秒），在此期间用户无法重复请求发送验证码。用户在收到验证码后，需在5分钟内将其填入页面的验证码输入框中。第三步：重置新密码。身份验证通过后，页面将跳转至重置密码环节。用户需要在此页面设置一个全新的密码。系统同样会在此处强制执行严格的密码复杂度校验（8-20位，包含大小写字母、数字及特殊符号），并要求用户在“确认新密码”输入框中再次输入一遍，以确保两次输入完全一致。如果不一致，系统会提示“两次输入的密码不一致，请重新输入”。第四步：完成重置并重新登录。当新密码成功提交并被系统后端安全更新至数据库后，页面会显示“密码重置成功”的绿色成功提示图标及文案，并在3秒后自动跳转回系统的初始登录页面。此时，用户即可使用刚刚设置的新密码顺利登录平台。"),
                ("1.7 多设备登录的具体限制规则", "考虑到AI短剧创作平台涉及到大量的计算资源消耗（如算力豆的使用）、敏感的创意剧本数据以及可能的企业团队协作权限，系统在底层架构上制定了严格的多设备登录限制规则。默认情况下，对于普通的个人注册账号，系统严格遵循“单一端点排他性登录”原则（Single Point of Presence）。这意味着同一个账号在同一时间内，只能在一台设备的同一个浏览器或客户端中保持在线状态。如果用户已经在办公室的台式电脑（设备A）上登录了平台，随后又在通勤途中的笔记本电脑（设备B）上使用相同的账号密码进行登录。当设备B的登录请求通过身份核验并成功建立新的会话（Session）时，系统后端会自动识别并定位到设备A上原有的旧会话。系统会立即强制使设备A的会话失效（Session Invalidation）。此时，如果设备A上的用户尝试进行任何需要与服务器交互的操作（如保存剧本、发起视频合成等），系统前端会捕获到认证失败的状态码（如HTTP 401 Unauthorized），并立即弹出一个覆盖全屏的强制下线提示框：“您的账号已在其他设备或地点登录。如果这不是您的操作，您的密码可能已经泄露，请立即修改密码。系统即将退出当前会话。”用户在设备A上只能点击“确定”按钮，随后页面将自动被重定向至登录界面。对于开通了高级企业版或团队版的高级账号，系统允许在后台由超级管理员配置“并发登录并发数”阈值（例如允许最多3台设备同时登录），但同样会详细记录每一台设备的登录时间、IP及操作日志，以便在出现数据冲突或安全事件时进行完整的溯源追踪。")
            ]
        },
        {
            "title": "2. 首页模块",
            "content": [
                ("2.1 首页板块布局结构", "登录成功后，用户将进入平台的核心枢纽——首页（Home/Dashboard）。首页采用了目前业界领先的现代化、响应式（Responsive）卡片式网格布局设计，确保在不同分辨率的显示器上都能呈现出完美的视觉效果和舒适的操作体验。整个首页在逻辑上被划分为四大核心功能区域：顶部全局导航栏（Top Navigation Bar）、左侧固定菜单栏（Sidebar Menu）、中央核心工作区（Main Workspace）以及右侧辅助信息面板（Right Panel）。顶部导航栏贯穿屏幕始终，左侧放置了平台的品牌Logo“智影”及产品Slogan，中间为全局模糊搜索框，右侧依次排列着消息通知铃铛图标、当前可用算力豆余额显示、帮助与支持入口，以及包含用户头像的个人中心下拉菜单。左侧菜单栏是平台各功能模块的快速切换通道，包含了“首页”、“我的创作”、“资产库”、“团队协作”、“数据中心”和“系统设置”等一级菜单项。中央核心工作区是首页视觉的焦点，自上而下依次为：顶部的大型动态轮播图（Banner）、中间的“快速开始”快捷功能入口矩阵（Quick Actions），以及下方的大型项目卡片列表（近期项目展示）。右侧辅助信息面板则集中展示了系统公告、平台最新动态、系统资源负载状态以及用户的核心统计数据汇总。这种结构分明、主次突出的布局，极大地降低了新用户的学习成本，使得用户能够迅速定位到所需的资源和功能入口。"),
                ("2.2 轮播功能操作与切换逻辑", "位于中央工作区顶部的大型动态轮播图（Banner Carousel）是平台向用户展示最新产品特性、核心教程、重要活动通知以及优质案例展播的重要视窗。轮播图组件采用了无缝滑动过渡特效，默认状态下以每隔5秒的固定频率进行自动轮播。当用户的鼠标光标悬停在轮播图区域内时，自动轮播机制将立即暂停，以便用户有充足的时间阅读当前展示画面的详细内容；当光标移出该区域后，自动轮播将在延迟2秒后恢复执行。在轮播图的左右两侧边缘，分别设有一个半透明的悬浮箭头按钮（左箭头与右箭头）。用户可以通过点击这两个箭头，手动强制向前或向后切换当前展示的幻灯片。同时，在轮播图的底部中央位置，排列着一排小圆点指示器（Pagination Dots），圆点的数量与当前轮播图的总页数一一对应。当前正在展示的页面对应的小圆点会呈现高亮的品牌色，其余圆点则为灰色半透明状态。用户不仅可以通过指示器直观地了解当前内容所处的位置，还可以直接点击任意一个小圆点，系统将通过平滑的动画迅速跳转并呈现该圆点所代表的对应轮播页面。此外，每一张轮播图均支持配置超链接，用户点击图片的主体区域，系统将在当前窗口或新开标签页中加载并展示对应的详细内容落地页（如某项新功能的详细使用教程文档）。"),
                ("2.3 快捷入口按钮的具体作用", "紧接着轮播图下方的是“快速开始”快捷入口功能矩阵（Quick Actions Grid）。这里集中放置了用户在日常高频使用的核心操作的快捷按钮，旨在最大化地缩短用户的操作路径。该矩阵通常由4至6个设计精美的大尺寸图标按钮组成，每个按钮均包含一个直观的矢量图标以及简明扼要的文字说明。核心按钮之一是“新建短剧项目”，点击该按钮将直接唤起一个全屏的项目初始化配置向导弹窗，用户无需繁琐地进入多级菜单即可快速立项。第二个重要按钮是“导入外部小说”，它为拥有现有文本IP的用户提供了一个一键直达的通道，点击后直接跳转至文本解析与导入工作台。第三个按钮是“智能分镜生成”，主要针对已经拥有剧本但急需进行画面拆解的用户，点击即可进入分镜工作台。第四个按钮是“数字资产库”，点击后将打开平台的公共及私有素材库，用户可以在此管理自己的角色模型、场景图片和配音音色。当用户的鼠标悬停在这些快捷按钮上时，按钮会呈现出轻微的上浮动画效果，并伴随着微弱的阴影加深，这种细腻的微交互（Micro-interaction）设计不仅提升了界面的质感，也给予了用户明确的可点击视觉反馈。通过这些精心编排的快捷入口，用户可以在进入首页的数秒内，迅速进入沉浸式的核心创作心流。"),
                ("2.4 数据统计模块展示内容与刷新规则", "右侧辅助信息面板的上方，或者在中央工作区项目列表的上方，设有一个重要的数据统计汇总模块（Data Dashboard）。该模块旨在帮助用户，特别是团队管理者和高频创作者，宏观、实时地掌握其在平台上的整体资产状况与创作进度。数据统计模块通常以四个并排的数据指标卡片呈现。卡片一展示的是“累计创作剧本数”，实时统计用户历史所有处于各个状态的剧本总量。卡片二展示的是“已生成视频总时长”，以分钟或小时为单位，精确累计用户通过AI合成的最终视频时长。卡片三展示的是“本月消耗算力豆”，详细记录当前自然月内因使用各项AI服务（如文本生成、图像渲染、视频合成等）而消耗的系统算力豆总额。卡片四展示的是“当前进行中项目”，直观反映用户目前正在并行推进的工作负载。这些数据的刷新规则采用了“页面加载即时拉取”与“局部无刷新更新”相结合的策略。当用户每次成功登录并加载首页，或者在浏览器中手动刷新页面时，前端会向后端发送一个异步的聚合数据请求（GraphQL或RESTful API），从数据库中拉取最新的统计快照并渲染。此外，如果用户在同一浏览器会话中，在其他页面（如视频合成页）完成了一项会改变统计数据的操作（例如成功合成了一段视频，扣除了100算力豆），当用户通过前端路由（Vue Router）无缝切换回首页时，系统会利用状态管理库（如Vuex或Pinia）中的全局状态数据，在不刷新整个页面的情况下，静默、平滑地更新数据卡片上的数值，甚至伴随着数字滚动的动态效果，确保用户看到的数据始终是绝对精准和实时的。"),
                ("2.5 消息通知入口触发逻辑与全量操作步骤", "顶部导航栏右侧的消息通知模块（Notification Center）是系统与用户进行异步信息传达的关键桥梁。该入口主要由一个“铃铛”形状的图标构成。当系统有任何新的、未被用户阅读的消息时，铃铛图标的右上角会实时出现一个带有数字的红色微标（Badge），数字精确表示当前未读消息的总条数。如果未读消息数量超过99条，微标通常会显示为“99+”。消息的触发逻辑涵盖了多种系统事件，主要包括：一是任务进度通知，例如用户在后台提交的一个耗时较长的“10分钟分镜视频渲染”任务完成时，系统会推送一条“您的视频《霸道总裁》第1集已渲染完成”的成功通知；二是系统公告，如平台即将进行停机维护、新版本功能上线发布等；三是团队协作通知，如用户被邀请加入一个新的创作团队，或者其负责的剧本被其他成员进行了修改与评论；四是资产变动通知，如用户的会员套餐即将到期，或算力豆余额不足10%的预警。用户点击铃铛图标后，系统会在图标正下方弹出一个悬浮的消息列表面板（Popover Panel）。面板顶部设有“全部标记为已读”和“查看全部消息”的快捷按钮。面板主体区域以时间倒序（最新的在最上方）列出最近的10条消息。每一条消息卡片包含消息类型图标、标题、简短摘要以及发生的时间戳。未读消息的卡片背景色通常会有轻微的底色区分（如极浅的蓝色），并且左侧可能有一个小红点。用户将鼠标悬停在某条消息上，该消息会被自动标记为已读（红点消失，微标数字相应减一）。如果消息内容较长或包含可操作链接，用户点击该消息卡片，系统将自动跳转至对应的业务详情页面（例如点击视频渲染完成通知，直接跳转至该视频的预览播放页面），从而形成了一个闭环的操作流转。")
            ]
        },
        {
            "title": "3. 灵感创作/小说导入模块",
            "content": [
                ("3.1 灵感创作模块的全量文本编辑功能", "灵感创作模块是平台为原创型编剧量身打造的沉浸式文本创作环境。进入该模块后，用户将面对一个极简、无干扰的全屏富文本编辑器（Rich Text Editor）。该编辑器的顶端悬浮着功能完备的格式控制工具栏。用户可以在这里执行全量的文本排版操作，包括但不限于：设置字体的加粗、倾斜、下划线、删除线；调整字体颜色与背景高亮色；设置段落的左对齐、居中对齐、右对齐及两端对齐；插入有序列表、无序列表；调整行间距与段间距等。为了适应长篇剧本的创作需求，编辑器还内置了强大的层级标题系统，用户可以一键将普通段落设置为H1至H6的标题格式，系统会根据这些标题在左侧自动实时生成一个可点击跳转的文档大纲导航树（Document Outline）。除了基础的排版功能，该模块深度集成了平台的AI辅助创作能力。在编辑器中，用户只需选中任意一段文本，或者在一个空行中输入特定的快捷指令（如斜杠“/”），即可唤出AI功能悬浮菜单。通过该菜单，用户可以要求AI对选中的段落进行“扩写细节”、“精简提炼”、“改变文风（如更加悬疑、更加搞笑）”、“纠正语法错误”，甚至是在思维枯竭时，只需输入一个简单的设定（如“男主在雨夜中发现了反派的秘密”），点击“AI续写”，系统便会自动调用后端的大语言模型，在数秒内生成多个版本的后续情节供用户挑选并一键插入正文。此外，编辑器具备毫秒级的本地自动实时保存功能（Auto-save），即使用户在创作过程中遭遇突发的浏览器崩溃或断电，也能确保每一个字的心血都不会丢失。"),
                ("3.2 素材上传格式与大小要求", "在剧本或灵感创作的过程中，文字往往无法完全表达创作者对视觉效果的构想，因此，灵感创作模块提供了丰富的附件与素材上传功能。在编辑器的工具栏中，设有一个“插入附件/素材”的通用按钮。点击后，用户可以通过拖拽或系统文件选择对话框上传本地资源。系统对各类素材的格式与大小有着极其严格且明确的校验规则。对于图像素材（常用于场景概念图或角色参考图），系统仅支持.jpg、.jpeg、.png以及.webp四种主流的高压缩比格式，且单张图片的文件体积被严格限制在10MB以内，图片分辨率长宽均不得超过4096像素。如果用户上传了不支持的格式（如.bmp或.tiff）或超大文件，系统会在上传进度条出现前立即进行前端拦截，并弹出红色的错误提示“上传失败：仅支持JPG/PNG/WEBP格式，且大小不能超过10MB”。对于音频素材（可能用于设定背景音乐基调或特定的角色配音参考），系统支持.mp3和.wav格式，单个文件大小上限设定为20MB，音频时长建议不超过5分钟。对于视频素材（用于动态的动作参考），系统仅支持采用H.264或H.265编码的.mp4格式文件，单文件大小严格限制在50MB以内。所有上传的素材在经过格式和大小的双重前端校验后，将通过分片上传（Multipart Upload）技术传输至后端的云存储服务器（如阿里云OSS或AWS S3），并在编辑器中以优雅的卡片或内联预览的形式展示，支持用户随时点击放大查看或播放。"),
                ("3.3 小说导入支持格式与校验规则", "对于拥有成熟网络小说版权或已经完成文字稿创作的用户，“小说导入”功能是他们进入AI短剧工业化生产流程的第一个核心关卡。在首页或创作模块的显眼位置，点击“小说导入”按钮后，将进入一个专属的导入工作台。平台目前全面支持业界最通用的三种文档格式的直接导入：即纯文本格式（.txt）、微软Word的旧版格式（.doc）以及新版格式（.docx）。这三种格式基本覆盖了市面上所有主流文字处理软件的输出标准。导入流程开始时，用户可以通过点击页面中央的虚线虚框区域或直接将文件拖拽至该区域来选定目标文件。此时，系统会立即启动严格的导入校验规则。首先是文件类型校验，系统不仅会检查文件的扩展名，还会深入读取文件的二进制头部签名（Magic Number），以防止用户将一个恶意脚本的后缀名强行修改为.txt后上传。一旦发现文件头部签名与扩展名不符，系统将坚决予以拦截并报错。其次是文件大小与字符数校验。为了保证后端大模型在后续处理时的性能与稳定性，系统规定单次导入的文件体积不能超过20MB。同时，对于纯文本文件，系统会在内存中快速扫描其字符总数，如果超过了系统设定的单次处理极限（例如100万字），系统会弹出友好的建议提示：“您导入的文本过长，为保证AI解析的质量与速度，建议您将文件拆分成多个部分后分批导入”。校验通过后，文件将被安全上传并暂存于服务器的内存处理队列中，准备进入下一步的深度解析环节。"),
                ("3.4 文本拆分工具的具体使用方法", "长篇小说动辄百万字，显然无法直接转换为一部几十集的短剧剧本。因此，在文件成功导入并被系统初步解析后，用户将进入至关重要的“文本拆分与提炼”工作台。在这个工作台上，左侧面板展示的是刚刚导入的原始小说完整文本内容，右侧面板则是空白的“剧本片段（Episode）”构建区域。平台提供了一套极为智能且灵活的文本拆分工具。第一种是“智能语义拆分”：用户只需在左侧面板的顶部工具栏点击“AI一键拆分”按钮，系统后端的自然语言处理（NLP）引擎便会自动对全文进行深度语义分析，识别出故事的高潮节点、场景转换点以及时间线的跳跃点，并据此自动将长篇小说切割成数十个结构相对完整的“短剧集（Episode）”草案，每个草案自动提取了核心摘要。第二种是“精准手动拆分”：如果用户对AI的自动拆分结果不满意，或者希望完全掌控节奏，可以采用手动模式。用户在左侧的原始文本阅读器中，使用鼠标高亮选中一段连续的文本（例如小说的第一章前三节），然后点击右键菜单中的“提取为新剧集”或者点击两面板中间的向右箭头按钮“>”，系统便会立即在右侧面板新建一个卡片，并将选中的文本作为该集的原始素材填入其中。用户可以在右侧的卡片上为这一集重新命名（如“第1集：龙王归来”），并可以对提取过来的文本进行进一步的删减和二次编辑。通过这种左右对照、拖拽提取的高效交互模式，用户可以像搭积木一样，将一部冗长的小说精准地解构并重组为符合短剧快节奏特征的剧本大纲结构。"),
                ("3.5 内容保存提交及导入失败的异常处理", "在用户完成了所有的文本拆分、编辑与剧集大纲重组工作后，便进入了最后的保存与提交环节。在拆分工作台的右上角，设有一个显眼的“确认并生成剧本项目”的蓝色主操作按钮。点击该按钮后，前端系统会收集右侧面板中所有已构建的剧集卡片信息（包括剧集标题、提取的原始文本片段、用户添加的备注等），将其序列化为一个复杂的JSON数据结构，并通过安全的HTTPS请求发送至后端接口。此时，页面会弹出一个全屏的加载遮罩层（Loading Overlay），提示“系统正在为您构建剧本工程，请稍候...”。后端接收到数据后，会在数据库中正式创建该剧本项目的所有关联表记录。一旦构建成功，系统会自动跳转至该新项目的“剧集管理”或“剧本创作”工作台，并弹出“项目导入并创建成功”的绿色提示框。然而，在整个导入和提炼的复杂流程中，难免会遇到异常情况。系统为此准备了周密的异常处理方案。如果因为网络剧烈波动导致提交请求超时（Timeout），系统会在遮罩层上显示“网络连接超时，请检查您的网络设置”，并提供一个“重试”按钮，用户无需重新进行拆分操作即可再次尝试提交。如果是因为后端服务器在解析特殊编码的.doc文件时遭遇内部错误（如文件加密或损坏），系统会在导入初期的校验阶段就明确抛出详细的错误信息：“文件解析失败：该文档可能已损坏或受到密码保护，请另存为无密码的.docx格式后重新尝试”。对于任何因不可抗力导致的崩溃，系统会依靠本地浏览器缓存（LocalStorage/IndexedDB）中每隔30秒保存的拆分进度快照，在用户刷新页面或重新进入该模块时，主动弹窗询问：“检测到您有未完成的导入拆分进度，是否恢复？”，最大程度地避免用户重复劳动。")
            ]
        },
        {
            "title": "4. 剧集管理模块",
            "content": [
                ("4.1 剧集新建与信息编辑", "剧集管理模块是整个短剧项目的控制中枢，用户在此对整部剧集的生命周期进行宏观调控。在项目详情页中，点击左侧菜单的“剧集管理”，即可进入该模块的工作台。界面中央以清晰的列表或网格卡片形式展示了当前项目下所有的剧集（Episode）。若要新建剧集，用户需点击列表右上角的“+ 新建剧集”按钮。点击后，系统会弹出一个模态对话框（Modal Dialog），要求用户填写基础的剧集元数据。必填项包括“剧集序号”（系统默认自动递增，如当前有5集，则默认填入第6集，用户也可手动修改）和“剧集标题”（如“男主的绝地反击”）。选填项包括“剧情摘要”（简述该集核心冲突，限500字）以及“预计时长”（用于后续算力豆预估）。信息填写完毕并点击“确定”后，新剧集将立即作为一条新记录插入到列表中。对于已经创建的剧集，用户随时可以进行信息编辑。在剧集列表的每一行末尾或卡片的右上角，设有一个“编辑”图标（通常为一支铅笔形状）。点击该图标，将再次唤出包含该剧集当前详细信息的表单弹窗。用户可以在此修改标题、更新摘要内容，甚至调整剧集的序号以改变其在全剧中的播放顺序。系统会对用户修改的序号进行实时冲突校验，如果用户将某集的序号修改为一个已经存在的序号（例如将第3集改为第1集），系统会自动提示“序号冲突，是否将原第1集及后续剧集顺延？”以保证剧集顺序的绝对逻辑连贯性。"),
                ("4.2 剧集状态切换与前置条件", "为了精确追踪每一集的生产进度，系统为剧集设计了一套严谨的状态机（State Machine）流转逻辑。每一集均包含四个核心状态：“草稿”（Draft）、“制作中”（In Production）、“渲染中”（Rendering）和“已完成”（Completed）。剧集新建后，其初始状态默认为“草稿”，此时列表中该集的状态标签显示为灰色。当用户点击该集进入“剧本创作”模块开始编写台词和设定分镜时，系统会自动或允许用户手动将其状态切换为“制作中”，此时标签变为醒目的蓝色。状态切换并非随意进行，而是受限于严格的前置条件。例如，从“草稿”或“制作中”切换到“渲染中”状态，其前置条件是：该剧集必须至少包含一个有效的分镜画面，且所有分镜的提示词（Prompt）和配音文本均已填写完毕。如果用户在信息不完整的情况下强行点击“发起视频渲染”按钮试图切换状态，系统会弹出红色的阻断提示：“状态切换失败：第2场第3镜缺少画面描述，请补充完整后再试”。当渲染任务在后端服务器集群中执行完毕并成功生成最终的视频文件后，系统会自动将该剧集的状态由“渲染中”（动态加载图标）平滑切换为最终的“已完成”（绿色打勾图标）。在“已完成”状态下，为了保护最终成片，系统默认锁定该剧集的剧本和分镜编辑权限，若用户确需修改，必须先手动将状态回退至“制作中”，系统会同时警示“回退状态将导致已生成的视频可能与剧本不符，是否继续？”。"),
                ("4.3 剧集删除与二次确认逻辑", "剧集删除是一项极具破坏性的高危操作，平台为此设计了严密的防误删机制。在剧集列表的操作列中，设有红色的“删除”按钮（通常为垃圾桶图标）。当用户点击某集的删除按钮时，系统绝不会立即执行删除动作，而是会立即弹出一个带有红色警告标志的二次确认弹窗（Confirmation Dialog）。弹窗中会用加粗字体明确提示风险：“您正在尝试删除【第X集：剧集标题】。此操作将永久抹除该集关联的所有剧本数据、分镜配置以及已生成的视频资产，且无法通过常规手段恢复！”。为了进一步防止用户因惯性点击“确定”而导致误删，对于包含大量资产的剧集，系统甚至会要求用户在一个文本输入框中手动键入“确认删除”四个汉字，或者输入该剧集的准确序号，只有当输入内容完全匹配时，原本处于置灰禁用状态的“最终删除”按钮才会被激活变为可点击的鲜红色。点击最终确认后，前端会向后端发送删除请求。考虑到数据库性能，系统后端通常采用“软删除”（Soft Delete）逻辑，即在数据库记录中打上删除标记并从用户界面中隐藏，但在物理存储上保留一段时间（如30天的回收站周期），以便应对极端情况下的数据找回需求。而在用户界面上，删除操作完成后，页面会平滑刷新，该剧集卡片会伴随一个淡出的动画从列表中永久消失。"),
                ("4.4 剧集搜索筛选与权限设置", "当一部短剧的集数达到几十甚至上百集时，如何在海量数据中快速定位特定剧集就显得尤为重要。剧集管理模块的顶部配备了一个功能强大的复合搜索与筛选工具栏。工具栏的最左侧是一个支持模糊匹配的全局搜索框，用户可以在此输入剧集的标题关键字或摘要中的核心词汇。随着用户的实时键盘输入（即时搜索 Debounce机制），下方的剧集列表会在毫秒级响应并动态过滤出匹配的结果。在搜索框右侧，排列着一组状态筛选下拉菜单。用户可以通过点击下拉菜单，勾选“仅显示草稿”、“仅显示制作中”或“仅显示已完成”，系统会立即对当前列表进行精准的条件过滤。这使得项目管理者能够瞬间总览当前有多少集处于瓶颈期，有多少集已经可以交付。此外，对于支持团队协作的企业版账号，剧集管理模块还深度集成了细粒度的剧集权限设置功能。在剧集的高级操作菜单中，包含一个“权限配置”入口。超级管理员或项目所有者可以点击进入，为每一集单独分配不同的操作人员。例如，可以将“第1集至第10集”的“剧本编辑权限”指派给编剧A，将“分镜渲染权限”指派给后期人员B。一旦权限被设定，当非授权人员尝试登录并访问该剧集时，他们可能只能看到只读模式的页面，或者根本无法在列表中看到该剧集（根据可见性权限的设置）。这种基于角色的细粒度访问控制（RBAC）机制，极大地提升了大型制作团队在多剧集并行开发过程中的安全性与协作效率。")
            ]
        },
        {
            "title": "5. 剧本创作模块",
            "content": [
                ("5.1 剧本模板分类与选择逻辑", "剧本创作模块是连接文学创意与视觉画面的核心翻译器。当用户在剧集管理中选择某一集并点击“进入创作”后，首先迎来的便是剧本模板的选择环节。系统内置了多套经过行业验证、专为AI短剧优化的专业剧本模板体系。这些模板主要分为三大类别：其一是“传统分场剧本模板”，这种格式严格遵循影视工业标准，以“场景标头（内/外、时间、地点）”为核心，将剧情划分为一个个独立的物理空间，适合具有专业影视编剧背景的用户；其二是“角色对话驱动模板”，这种模板极大弱化了复杂的环境描写，界面左侧为角色头像与名称，右侧为大段台词，极其适合制作以密集对话冲突为主的都市情感剧或悬疑推理剧；其三是“AI视觉流模板”，这是平台独创的特色模板，它强制要求用户在输入每一段文字时，必须将其拆分为“画面视觉描述（Prompt）”与“听觉声音描述（Audio）”双轨并行，直接为后续的AI视频渲染提供最结构化的数据。在新建剧本时，系统会弹出一个包含这三类模板缩略图及详细说明的向导页面。用户点击任意一个模板卡片，系统右侧会展示该模板的排版示例和适用场景建议。用户选定模板并点击“应用此模板”后，编辑器将立即按照该模板的结构加载空白框架。需要注意的是，一旦在一个剧集中选定并应用了某种模板开始创作，为了保证该集内部数据结构的统一性，系统通常不允许中途随意切换回其他差异巨大的模板格式，除非用户清空当前所有内容。"),
                ("5.2 角色台词录入与场景标注功能", "进入正式的编辑界面后，角色台词的录入与场景标注成为了最为高频的操作。在编辑器中，系统提供了极其流畅的键盘快捷键驱动体验。用户在空白行按下“Tab”键或特定的快捷组合（如Ctrl+R），系统会自动在当前行首插入一个醒目的角色名称输入框（或下拉列表）。如果该角色是首次出现，用户可直接键入其名称并回车，系统会自动将其注册到该剧集的“角色资产库”中；如果角色已存在，下拉列表会提供自动补全建议，用户只需使用方向键选择即可。角色设定完成后，紧随其后的输入区域便是该角色的专属台词框。为了让后续的AI配音（TTS）更加生动，台词框旁边还附带了一个细微的“情绪标签”下拉菜单，用户可以为这句台词标注“愤怒”、“悲伤”、“狂喜”等情感指导。在台词之间或之前，是至关重要的场景标注（Scene Heading）功能。用户点击工具栏的“插入场景”按钮，或者输入快捷指令“#”，即可创建一个高亮的场景分割区块。在这个区块内，用户需要通过标准化的下拉菜单依次选择“内景/外景（INT./EXT.）”、“具体地点（如：豪华别墅客厅）”以及“时间（日/夜/黄昏）”。场景区块的建立，不仅在视觉上将长篇剧本切割得层次分明，更重要的是，系统后端的AI引擎会将这些场景属性提取为全局环境变量。当渲染该场景下的分镜时，AI会自动为画面加上符合设定的光影特征（如“夜”设定会自动增加暗部细节和室内人工光源），极大地减少了用户后续手动调节画面提示词的繁琐工作。"),
                ("5.3 版本回溯机制的触发与操作流程", "在剧本反复打磨修改的过程中，用户不可避免地会遇到思路卡壳，想要找回昨天甚至一周前某个绝佳的剧情设定的情况。为此，平台构建了极其强大且细致的版本控制与回溯机制（Version History）。该机制分为“系统自动存档”与“用户手动打点”两种触发模式。系统默认每隔5分钟，或者在用户停止键盘输入超过30秒时，在后台静默创建一个包含当前全文快照的增量微版本。此外，在每次进行重大结构调整前，用户可以点击编辑器右上角的“创建里程碑”按钮，手动输入版本备注（如“修改了男主反杀的逻辑”），系统会永久锁定保存这一重要版本。当用户需要找回历史内容时，只需点击顶部菜单栏的“历史版本”图标，界面右侧将立即滑出一个时间线面板（Timeline Drawer）。面板中以时间轴的形式垂直排列着所有历史版本的节点，手动打点的里程碑版本会以高亮的特殊图标标出。用户点击任意一个历史节点，左侧的主编辑器区域将立即切换为“差异对比模式”（Diff View）。在这个模式下，系统会用绿色高亮显示当前版本新增的内容，用红色带删除线的格式标出已被删减的内容，就如同专业代码管理工具Git一般清晰直观。用户在仔细核对并确认这就是想要恢复的段落后，可以点击该节点下方的“恢复此版本”按钮。系统会弹出二次确认框：“恢复历史版本将覆盖当前所有未保存的修改，强烈建议您先将当前状态存为里程碑。是否继续恢复？”确认后，主编辑器瞬间重置为该历史节点的内容，帮助用户实现完美的时空穿梭与灵感找回。"),
                ("5.4 协作编辑权限与剧本导出流程", "针对企业级团队的工业化生产需求，剧本创作模块深度融合了多人实时在线协作（Real-time Collaborative Editing）功能。当多个被授予“编辑权限”的团队成员同时打开同一集的剧本页面时，系统会依托底层的WebSocket长连接技术建立实时同步通道。在界面的右上角，会显示当前所有在线协作者的圆形头像列表。在编辑器正文中，每个协作者的鼠标光标位置都会实时显现，并带有一个专属颜色的小标签，标签上标有其姓名（例如，红色的光标旁写着“主编李某”）。为了防止多人在同一瞬间修改同一段落导致数据冲突（Race Condition），系统采用了先进的OT（Operational Transformation）或CRDT算法来合并冲突，或者在UI层面采取“段落级锁定”策略：当用户A正在编辑第三个场景时，该场景区块会对用户B呈现浅灰色的锁定状态，用户B只能阅读而无法修改，直到用户A的光标移出该区块。当剧本彻底定稿，需要流转到平台外部（如发送给线下演员、投资人审核或向版权局备案）时，剧本导出功能便发挥了关键作用。用户点击右上角的“导出剧本”按钮，系统会提供一个丰富的格式配置对话框。用户可以选择导出为高度保真的PDF格式（适合直接打印与阅读）、可二次编辑的Word（.docx）格式，或者是纯文本（.txt）格式。在导出设置中，用户还可以自定义是否在页眉页脚附带“剧本项目名称”、“作者水印”以及“页码”等版权保护信息。点击“确认导出”后，系统后端会迅速调用文档生成引擎排版并生成文件，浏览器随之自动触发下载任务，将标准化的剧本文件安全保存至用户的本地硬盘中。")
            ]
        },
        {
            "title": "6. 主体设置模块",
            "content": [
                ("6.1 账号主体信息修改规则", "主体设置模块是用户管理其在平台上数字身份和底层配置的核心后台。通过左侧菜单栏底部的“系统设置”或点击右上角头像下拉菜单中的“账号设置”，用户可进入该模块。在“基础信息”选项卡中，展示了账号的主体概况。对于个人用户，这里包括昵称、个人简介、绑定的手机号码和电子邮箱。修改昵称和简介相对简单，用户直接在输入框中修改并点击“保存更改”即可，系统会进行基础的敏感词过滤校验，若包含违规词汇则会弹出红色警告“昵称包含系统保留词汇或敏感词，请修改”。而修改绑定的手机号码或邮箱，则涉及账号安全的核心链路，必须经过严密的双重验证。用户点击“修改手机号”后，系统首先会要求用户向当前旧手机号发送验证码，或者输入当前账号的登录密码以证明其为本人操作。验证通过后，才能进入下一步，输入全新的手机号码，并再次接收及填入新手机号的验证码。只有当新手机号的验证码也完全正确时，系统才会正式将数据库中的绑定关系更新为新号码，并立即向旧号码发送一条“您的绑定手机已更改”的通知短信。对于企业级主体账号，其基础信息还包括企业名称、统一社会信用代码、法定代表人姓名等法定信息。由于这些信息直接关系到发票开具、版权归属以及大额资金流转，系统规定，一旦企业主体认证通过，这些核心字段将处于“锁定只读”状态。如果企业确实因工商变更需要修改这些信息，用户无法直接在界面上编辑，必须点击旁边的“申请变更”按钮，重新提交全套的工商变更证明文件材料，走人工审核通道。"),
                ("6.2 资质上传格式要求与审核流程", "在“资质认证”选项卡下，系统处理用户从个人向专业创作者或企业主体的身份跃迁。为了获取平台的高级API访问权限、开启作品的商业化分发收益或解除某些功能的高级限制，用户必须完成实名或企业资质认证。对于个人实名认证，用户需要上传身份证的正反面高清照片。系统要求图片必须为.jpg或.png格式，大小在500KB至5MB之间，以确保图片既不过于庞大影响传输，又足够清晰以便机器识别。上传后，系统前端会调用OCR（光学字符识别）接口进行初步的图片质量检测，如果图片模糊、反光严重或边缘残缺，系统会立即提示“图片质量不佳或未检测到有效证件信息，请重新拍摄上传”。对于企业资质认证，流程更为复杂。用户必须上传加盖了企业红色公章的《营业执照》副本彩色扫描件。除了图片格式和大小要求外，系统还提供了一个专用的《平台入驻授权委托书》模板供用户下载。用户需打印、填写、法人签字并盖章后，将其扫描为PDF或图片格式再次上传。所有资质文件上传完毕并点击“提交审核”后，系统的状态将变更为“审核中（Pending Review）”。此时，资料会进入平台后台的人工运营审核队列。通常情况下，审核周期为1至3个工作日。如果审核通过，用户会收到系统站内信和短信双重通知，账号状态自动升级；如果审核不通过，系统会将状态变更为“审核驳回（Rejected）”，并在页面上用醒目的红色字体详细列出驳回原因（例如：“营业执照公章不清晰”或“授权书缺少法定代表人签字”）。用户需根据驳回原因，重新修改资料并再次发起审核申请流程。"),
                ("6.3 支付配置的绑定步骤", "支付配置是连接用户数字资产与现实资金的重要桥梁，主要用于用户在平台购买算力豆、充值VIP会员套餐，以及在未来实现作品收益的提现。在“支付与财务”选项卡中，用户可以管理其绑定的支付渠道。平台目前主流支持微信支付、支付宝以及企业对公银行账户转账三种模式。以绑定支付宝为例，用户点击“添加支付方式”并选择“支付宝”后，系统会弹出一个安全绑定弹窗。为了保证资金安全，系统不要求用户输入支付宝的登录密码，而是采用OAuth2.0授权机制。系统会生成一个专属的授权二维码，用户需使用手机端的支付宝App扫描该二维码，并在手机端确认授权“允许AI短剧平台进行扣款与结算服务”。手机端确认后，PC端网页会通过轮询（Polling）或WebSocket接收到授权成功的信号，并自动刷新页面，此时支付宝账号（通常进行脱敏处理，如隐藏中间几位数字）将出现在已绑定的支付列表中。如果是企业用户需要配置对公银行账户，用户需要准确无误地填入开户银行名称（支持模糊搜索选择联行号）、银行账号以及开户企业名称（系统会强制校验该名称必须与已认证的企业资质名称绝对一致）。提交银行信息后，系统可能会采用“小额打款认证”的方式进行验证，即平台向该银行账户汇入一笔随机的极小金额（如0.13元），用户在查询到银行流水后，需回到平台填入收到的准确金额数值，金额匹配无误后，该对公账户才算正式绑定成功并激活。"),
                ("6.4 个性化偏好设置与系统校验规则", "除了严肃的账号与财务信息，“偏好设置”选项卡赋予了用户根据自身习惯定制平台交互体验的自由。在这里，用户可以进行全方位的个性化调整。在“视觉主题”设置中，用户可以一键切换“浅色模式（Light Mode）”、“深色模式（Dark Mode/夜间模式）”或者选择“跟随系统时间自动切换”。在深色模式下，整个平台的背景将变为深灰色或纯黑色，文字变为高亮色，极大地缓解了编剧和后期人员在夜间长时间面对屏幕的视觉疲劳。在“通知提醒”设置中，系统提供了一个极其细致的矩阵式开关列表。用户可以分别针对“渲染任务完成”、“收到团队邀请”、“系统余额预警”等不同类型的事件，独立开启或关闭“站内信”、“浏览器桌面推送（Push Notification）”、“短信提醒”以及“邮件提醒”的通道。例如，用户可以关闭烦人的日常系统邮件，但保留余额预警的短信通知，以防止关键任务因欠费而中断。在“编辑器默认配置”中，用户可以预设自己在剧本创作时的默认模板、默认字体大小以及是否默认开启“AI语法纠错”功能。所有的偏好设置在用户点击对应开关或保存按钮的瞬间，前端都会通过API异步将配置同步至后端数据库的用户配置表（User Preferences Table）中进行持久化存储。在此过程中，系统后端会进行基本的数据类型校验，确保传入的主题字符串是合法的枚举值，或者传入的字体大小在合理的区间范围内。一旦保存成功，这些偏好设置将与用户的账号深度绑定，无论用户随后在公司还是家中的任何一台设备上登录平台，系统都会在瞬间加载并恢复其独一无二的个性化工作环境。")
            ]
        },
        {
            "title": "7. 分镜视频模块",
            "content": [
                ("7.1 分镜上传规格与排序调整方法", "分镜视频模块是AI短剧平台将文字剧本转化为最终视觉盛宴的工业化流水线核心。在剧本创作完成并流转至该模块后，用户首先面对的是分镜（Storyboard）的管理工作台。界面呈现为一个横向滚动的轨道或垂直的卡片列表，每一个卡片代表剧本中的一个镜头（Shot）。虽然平台主打AI自动生成画面，但同样支持专业团队导入手绘或外部构建的参考分镜图以精确控制视觉走向。点击分镜卡片上的“上传参考图”区域，系统要求上传的图片必须严格遵守规格：格式限定为高保真的PNG或JPG，为匹配目前主流的短视频平台（如抖音、快手）竖屏生态，系统强烈建议并会优先校验图片的宽高比是否为9:16（如1080x1920像素）。如果用户上传了16:9的横屏图片，系统内置的智能裁剪工具会立即弹出，要求用户手动框选出9:16的核心视觉区域，或者选择“智能居中填充黑边”的处理策略，以确保后续视频合成时画面比例的绝对一致性。在分镜列表的管理上，调整镜头顺序的操作被设计得极其直观。用户只需将鼠标光标悬停在任意一个分镜卡片上，卡片边缘会出现一个“拖拽手柄”（通常为六个小圆点组成的图标）。用户按住鼠标左键，即可将该分镜卡片在轨道中随意拖拽移动（Drag and Drop）。在拖拽过程中，其他卡片会平滑地向两侧避让，留出插入的空隙。当用户松开鼠标，分镜便会精准地嵌入新的位置，同时系统会自动重新计算并刷新所有分镜的全局序号（如原第5镜变为了第3镜）。这一流畅的交互极大地便利了导演在后期对叙事节奏的微调与重组。"),
                ("7.2 视频合成触发条件与前置要求", "分镜配置就绪后，接下来便是最激动人心也最为耗费算力资源的“视频智能合成”环节。在分镜工作台的右上角或底部固定栏，设有一个醒目的主色调“开始合成（Render Video）”按钮。然而，这个按钮并非随时处于激活可点击状态。系统在底层设定了一系列严格的触发条件与前置数据完整性要求，以避免用户因误操作而白白浪费宝贵的算力豆。前置要求一：数据完整性校验。系统前端会遍历当前剧集的所有分镜卡片，检查是否每一个分镜都已配备了合法的“画面提示词（Image Prompt）”或者“参考图片”，并且是否每一个需要发声的角色都已关联了具体的“台词文本”并配置了对应的“AI音色模型”。如果存在任何一个空缺，合成按钮将处于置灰不可用状态，且鼠标悬停时会通过Tooltip提示具体缺失信息的卡片序号（例如：“第12镜缺少画面描述”）。前置要求二：算力余额校验。当数据完整性校验通过，用户点击“开始合成”时，系统并不会立刻启动渲染，而是会弹出一个“合成任务确认单”。该确认单会根据当前剧集的总分镜数、预计生成的视频总时长以及用户选择的渲染精度（如标清720P、高清1080P或超清4K），精确计算出本次任务将消耗的算力豆数量（例如：“本次渲染预计消耗 1250 算力豆”）。同时，系统会与用户账户的当前余额进行实时比对。如果余额充足，用户点击“确认扣费并渲染”，任务才会正式提交至后端的GPU渲染集群；如果余额不足，确认按钮将变为红色的“去充值”，直接引导用户进入支付充值流程。这种“先算账，后渲染”的机制，充分保障了交易的透明性。"),
                ("7.3 合成进度查看与后端处理机制", "视频合成是一个涉及复杂AI大模型推理（如文生图、图生视频、TTS语音合成、音视频自动对齐对口型等）的重度异步计算过程，通常需要数分钟甚至更长时间。任务提交后，界面会自动切换至“渲染任务监控”视图。在这个视图中，用户可以清晰地看到当前剧集正在被处理的实时状态。界面中央会显示一个极具科技感的动态环形进度条或波浪形进度条，百分比数字从0%开始逐渐跳动。为了缓解用户在漫长等待中的焦虑感，进度条下方会滚动显示系统当前正在执行的具体子任务节点日志，例如：“[正在初始化渲染引擎...] -> [正在生成第1-5镜基础画面...] -> [正在进行AI语音合成与口型匹配...] -> [正在进行最终视频通道合并与压制...]”。在后端机制上，平台采用了高可用的分布式消息队列（如RabbitMQ或Kafka）来调度任务。用户的渲染请求首先被包装成一条消息投入队列，后台闲置的GPU工作节点（Worker Node）竞争获取该任务并开始执行。如果某个工作节点在渲染途中因硬件故障崩溃，消息队列的确认机制（ACK）会察觉到异常，并将该任务重新分配给其他健康的节点继续执行，从而保证了任务的高可用性。用户无需全程死守在进度页面，他们可以自由切换到其他模块继续编写下一集的剧本。当后台渲染任务100%彻底完成时，系统会通过前文提到的全局消息通知中心（顶部小铃铛）以及浏览器右下角的弹窗（Web Notification）向用户发出清脆的提示音和成功通知，提醒用户成片已准备就绪。"),
                ("7.4 视频预览下载与发布流程的全部操作细节", "当收到渲染完成的通知后，用户点击链接即可进入最终的“视频预览与发布（Preview & Publish）”工作台。在这个页面占据核心位置的是一个功能完备的自定义网页视频播放器（Video Player）。播放器支持常规的播放/暂停、音量调节、全屏切换，以及专为审片设计的逐帧步进（Frame-by-step）和倍速播放（0.5x至2.0x）功能。用户在此仔细审视AI生成的每一帧画面与音频的契合度。如果对成片质量完全满意，用户可以进行下载或发布操作。在播放器右侧的工具栏中，点击“下载到本地”按钮，系统会弹出一个格式选择框，用户可选择下载包含完整平台水印的免费版（如适用），或者消耗少量算力豆下载去除平台水印的纯净版MP4原文件。系统将生成一个带有效期的临时防盗链（Signed URL）开始高速下载传输。如果用户希望直接将作品推向市场，可点击“一键发布”按钮。发布流程包含三个严谨的步骤。第一步是填写发布元数据：用户需要为短剧上传一张吸引眼球的封面海报（Cover Image，同样要求9:16，大小不超过5MB），填写引人入胜的剧集简介，并选择合适的分类标签（如“霸总”、“甜宠”、“逆袭”）。第二步是内容合规性机审：点击提交后，系统后端的AI安全引擎会在几秒钟内对视频画面、台词文本及配音进行黄赌毒等敏感违规内容的快速扫描（Content Moderation）。第三步是人工审核与上架：机审通过后，作品状态变更为“等待人工复核”。平台运营人员将在后台最终确认作品未侵犯他人版权且符合社区规范。一旦人工审核通过，视频状态将正式更新为“已发布（Published）”，作品将立即出现在平台面向C端观众的“短剧大厅”中，开始接受用户的点击、点赞与评论，正式开启其商业化变现的生命周期。")
            ]
        },
        {
            "title": "8. 会员中心模块",
            "content": [
                ("8.1 会员套餐介绍与权益查看", "会员中心模块是平台构建商业闭环与提供差异化尊享服务的核心枢纽。通过左侧菜单栏的“会员中心”或点击首页的“升级VIP”醒目按钮，用户可进入该模块。会员中心的首页顶部通常以极具视觉冲击力的横向对比卡片（Pricing Cards）形式，向用户清晰地展示当前平台提供的所有会员套餐层级。常见的套餐层级划分为“免费基础版（Free）”、“专业创作者版（Pro）”和“企业团队版（Enterprise）”。每个套餐卡片上都用大号加粗字体标明了价格（如“￥99/月”或“￥998/年”）。在价格下方，是一条条用绿色勾号或灰色叉号标示的详细权益清单（Feature Matrix）。例如，“专业创作者版”的卡片上会明确列出其专享权益：每月免费赠送10000算力豆、解锁所有顶级画质（4K）渲染权限、解锁全部高级情感AI音色库、单次可导入小说字数上限提升至50万字、以及去除生成视频的平台默认水印等。这种直观的对比设计，能够迅速激发用户的升级欲望。对于已经开通了会员服务的用户，会员中心首页会自动切换为“我的权益概览”视图。在这个视图中，卡片被替换为一个专属的金色或黑金质感的数字身份卡（ID Card），卡片上清晰地显示了当前账号的会员等级、会员专属皇冠标识，以及最核心的“会员到期时间（如：2026年12月31日到期）”。在身份卡下方，有几个动态环形图表，实时展示当前各项权益的剩余使用额度，例如“本月剩余免费算力豆：8500/10000”，帮助用户精确掌握自己的资产消耗进度。"),
                ("8.2 开通与续费的操作流程及到期提醒", "无论是新用户首次开通会员，还是老用户进行续费，其操作流程都被设计得极致流畅且安全。用户在挑选好心仪的套餐卡片后，点击卡片底部的“立即开通”或“立即续费”按钮，页面将平滑过渡至订单结算收银台（Checkout Page）。在收银台页面左侧，系统会详细列出本次交易的订单明细，包括套餐名称、生效周期（1个月/3个月/12个月）、原价以及当前可能享受的折扣优惠。如果用户手中有平台发放的促销优惠券或兑换码，可以在专门的输入框中填入并点击“应用”，系统会立即重新计算并刷新右侧的“最终应付总额”。在右侧的支付方式选择区域，用户可以选择使用前文在“主体设置”中绑定的默认支付渠道，或者临时选择使用微信、支付宝扫码支付。点击“确认支付”后，若选择扫码，屏幕中央会弹出一个包含支付二维码的安全模态框。用户使用手机完成付款动作后，平台的支付网关（Payment Gateway）会通过异步回调接口（Webhook）在秒级时间内接收到第三方支付平台的成功凭证。此时，收银台页面会自动跳转至“支付成功”的庆祝页面，并伴随撒花等微动效，提示“恭喜您，专业版会员已生效，各项专属权益已为您点亮”。为了防止用户因遗忘而导致服务中断，系统设计了周密的会员到期提醒逻辑。当用户的会员资格剩余天数小于等于7天时，用户每次登录系统，首页顶部都会出现一条醒目的黄色横幅（Banner）警告：“您的专业版会员还有X天即将到期，为避免影响您的创作权益，请尽快续费”，并附带一个一键跳转至续费页面的链接。如果用户开启了自动续费订阅（Auto-Renewal），系统则会在扣款前3天通过短信和邮件发送扣款预通知，确保用户的知情权。"),
                ("8.3 订单管理与发票申请的全部步骤", "在会员中心模块的子菜单中，包含了一个详尽的“订单与账单管理（Order History）”页面。这是用户查阅其在平台上所有资金往来流水的权威账本。页面主体是一个多维度可筛选的数据表格。表格的列头包括“订单编号（一串唯一生成的字母数字组合）”、“交易时间（精确到秒）”、“交易类型（如：开通会员、购买算力豆包、算力豆单次渲染消耗）”、“交易金额/消耗数量”以及“当前状态（支付成功/已取消/退款中）”。用户可以利用顶部的日期选择器（Date Picker）筛选出特定月份的交易流水，或者在搜索框中直接输入订单号进行精准定位。对于企业用户或有报销需求的个人用户，开具发票是必不可少的环节。在每一条状态为“支付成功”且包含实际法币金额的订单记录右侧操作列，都设有一个“申请发票（Request Invoice）”的文字按钮。点击该按钮后，系统会弹出一个发票信息填报表单。平台默认提供增值税普通电子发票和增值税专用纸质发票两种选择。用户需仔细填写发票抬头（必须与企业营业执照一致）、纳税人识别号、注册地址、开户银行及账号等法定信息。为了简化操作，系统会自动提取并填入用户在“主体设置”中已经通过资质认证的企业信息。用户还可以选择将多个未开票的订单勾选合并，进行“合并开票”。在填入用于接收电子发票的有效电子邮箱地址，并仔细核对金额与信息无误后，点击“提交申请”。系统后台的财务模块会接收到该请求，并在约定的工作日内（通常为1-3个工作日）完成开具，并将包含PDF格式电子发票文件的邮件发送至用户指定的邮箱中。订单表格中的对应记录状态也会随之更新为“已开票”，避免重复申请。"),
                ("8.4 会员降级与账号注销的规则及操作流程", "平台充分尊重用户的自由选择权，在会员中心不仅提供了便捷的升级通道，也同样制定了清晰、规范的降级与注销退出机制。关于会员降级（Downgrade），这通常发生在使用自动续费订阅模式的用户身上。如果用户当前处于高级的“企业团队版”，但发现团队规模缩小，希望在下个月降级为“专业创作者版”。用户需在“我的权益”页面找到“管理订阅”入口。点击后，选择“更改套餐层级”并选择低级别套餐。系统会弹出详细的降级影响说明：“您当前的团队版权益将保留至本计费周期结束（如本月31日）。从下个周期开始，您将被降级为专业版。降级后，您的最大团队成员数将从50人缩减至5人，超出名额的成员将被自动冻结权限；您存储在企业公共空间的超额资产可能会被限制访问。是否确认降级？”用户勾选“我已了解风险”并确认后，降级指令生效，但实际权益的削减会在当前周期彻底结束后才执行。而关于账号注销（Account Deletion），这是一个最为彻底、不可逆的毁灭性操作。用户需进入“系统设置”的“安全中心”或会员中心的最底层菜单，找到极其隐蔽但符合合规要求的“注销账号”入口。点击后，系统会启动严格的注销前置校验条件：首先检查账号内是否还有未消耗完的付费算力豆（如有，提示需先申请退款或放弃权益）；其次检查是否有尚未完结的提现订单或进行中的渲染任务。只有当所有资产清零、任务完结时，系统才会允许进入实质注销流程。系统会向用户绑定的手机发送最后一次最高级别的安全验证码，并要求用户勾选一份长篇的《账号注销不可恢复风险确认协议》。验证通过并提交注销申请后，账号会被立即强制登出。为了防止用户恶意逃避法律责任或提供反悔期，系统通常会设定一个15天的“注销冷静期（Cooling-off Period）”。在此期间，用户若重新登录，注销申请将被自动撤销；若15天内未再登录，系统的定时任务脚本将在后台彻底、永久地擦除该账号在数据库中的一切痕迹、个人信息及关联的剧本资产，实现彻底遗忘。")
            ]
        },
        {
            "title": "9. 团队管理模块",
            "content": [
                ("9.1 团队成员的邀请流程与权限变更生效时间", "对于立志于打造爆款AI短剧的专业工作室而言，单打独斗往往难以应对庞大的工作量，因此团队管理模块成为了企业版账号的重中之重。作为团队的超级管理员或所有者，点击左侧菜单的“团队协作”即可进入该模块的控制中心。界面主体是一个团队成员的通讯录列表。若要扩充团队，管理员需点击页面右上角的“邀请新成员”蓝色主按钮。系统提供了两种灵活的邀请机制。第一种是“定向邮件/短信邀请”：管理员在弹出的表单中输入被邀请人的邮箱地址或手机号码，并预先为他们设定好即将担任的角色（如“编剧”或“后期”），点击发送后，系统会通过官方通道向对方发送一条包含专属、一次性、带加密签名的邀请链接。对方点击链接并完成注册/登录后，即可直接自动归入该团队麾下。第二种是更为便捷的“邀请码/链接分享”：系统生成一串有效时长为24小时或7天的邀请链接或六位字母数字邀请码。管理员可将其复制并通过企业微信或钉钉等即时通讯工具发送给工作群。成员通过链接访问时，需主动申请加入，随后管理员在系统的“待审核邀请”列表中点击“同意”方可放行。当成员成功加入或其在团队中的权限被管理员修改时（例如从普通“创作员”被提拔为拥有审核权的“审核员”），这一权限变更的生效时间是实时的（Real-time）。系统底层的身份认证与授权模块（IAM）会在数据库层面立即更新权限映射表，并强制刷新该用户当前所有在线终端的Token令牌。这意味着，如果该成员此时正处于登录状态，他在几秒钟内刷新页面或点击菜单时，就会发现自己瞬间解锁了之前灰色的“剧集审核”按钮，无需重新注销并登录，实现了无缝的协作体验升级。"),
                ("9.2 角色权限的分配规则（管理员/创作员/审核员等）", "团队管理的核心在于建立一套严密、科学、权责分明的角色权限控制体系（RBAC - Role-Based Access Control）。在成员列表的“角色管理”子页面中，系统预设了几个典型的行业标准角色，并且支持企业级用户自定义创建新角色。系统预设的最高权限是“超级管理员（Owner）”，该角色具有平台的绝对控制权，包括但不限于团队解散、财务支付配置、算力豆购买、全局系统设置以及对任何角色的任意修改权，此角色通常由公司法人或项目总负责人担任。其次是“项目管理员（Admin）”，该角色可以创建新的短剧项目、管理所有的剧集列表、邀请或移除普通成员，但无法触及敏感的财务支付与企业主体资质模块。再往下是基层的执行者“创作员（Creator/Writer）”，系统将其权限严格限制在“内容生产”领域。创作员只能访问被指派给自己的具体剧集，可以在编辑器中进行台词编写、素材上传和分镜提示词修改，但他们通常没有权限点击“开始合成”按钮去消耗宝贵的团队算力豆，也无权删除任何剧集记录。为了把控质量与控制成本，系统还设立了“审核员（Reviewer）”角色。当创作员完成了一集剧本或分镜的配置后，需点击“提交审核”，此时任务流转至审核员的工作台。审核员拥有对剧本和分镜的“审批通过”或“驳回修改”权限，更为关键的是，通常只有审核员或更高级别的管理员，才拥有最终触发后端GPU集群“发起视频渲染”的高级执行权限。通过这种角色权限的精细拆分与互相制约，团队能够在保证创作效率的同时，最大限度地降低误操作风险与资金浪费。"),
                ("9.3 成员退出与移除的操作步骤及数据处理规则", "在团队的人员流动中，成员的退出与移除是不可避免的常规管理操作。平台为此制定了严谨的流程与极其重要的数据交接规则。如果是成员因个人原因主动离开，该成员需在自己的“账号设置”或“所属团队”页面中，找到并点击“退出当前团队”的红色警示链接。系统会弹出二次确认框，告知其退出后将立即丧失对团队所有项目资产的访问权。而更常见的是管理员主动清理团队人员。在管理员的成员列表视图中，每一位成员信息行的最右侧操作列，都设有一个“移除成员”的操作项。点击后，系统会弹出一个至关重要的模态对话框。对话框中不仅需要管理员再次确认移除意图，更核心的是必须做出“数据资产处理决断”。系统会提示：“该成员（如张三）目前在团队名下创建了 15 篇剧本草稿和 30 个私有上传素材。请选择如何处理这些资产？”此时，管理员必须在两个单选按钮中做出选择：选项A是“彻底删除该成员产生的所有未交接私有数据”；选项B是更为稳妥的“将该成员产生的所有数据资产强制移交并继承给团队内的另一位指定成员（如李四）”。只有当管理员选择了资产接收人并点击“确认并移除”后，系统后台才会开始执行复杂的数据表外键关联（Foreign Key）更新操作，将数以千计的数据行所有权平滑转移给新主人，随后彻底切断被移除成员与该团队的权限关联。这种严密的数据处理规则，确保了企业在遭遇核心员工离职突发状况时，项目数据与创意资产绝不会流失或成为无法访问的“孤儿数据”。"),
                ("9.4 操作日志查看与团队空间管理的所有功能", "为了满足企业级用户对信息安全审计、事故溯源以及工作量绩效评估的强烈需求，团队管理模块内置了专业级别的“系统操作日志（Audit Logs）”功能。在成员列表旁的“操作日志”选项卡中，管理员面对的是一个记录了团队内一切风吹草动的大型数据仪表盘。这里的日志记录达到了极细的颗粒度级别（Fine-grained Logging）。无论是“管理员A在昨天上午10点修改了成员B的权限”，还是“编剧C在昨晚深夜2点删除了第5集的第二场戏”，亦或是“后期D在今天凌晨发起了一次消耗500算力豆的视频渲染请求”，每一条操作动作、操作人、发生的确切时间戳、操作来源的IP地址，都被系统后端的日志服务不可篡改地记录在案，并以结构化表格的形式呈现给管理员。管理员可以利用顶部的多维筛选器，按照“操作人”、“时间范围”或“操作类型（如仅查看‘删除’操作）”进行快速排查，从而在发生剧本内容莫名丢失或算力豆异常消耗时，能够迅速锁定责任人与事件脉络。此外，“团队空间管理（Team Workspace）”是另一个关键的协作基础设施。在这里，管理员可以分配和管理团队公共存储网盘（Cloud Storage）的配额。团队空间类似于一个共享的数字保险库，团队成员可以将通用的角色三维模型、标准的片头片尾视频模板、或者常用的公版音效库上传至“公共素材目录”中。在这个目录下的所有资产，团队内的每一位创作员在进行剧本创作或分镜配置时，都可以直接跨项目无缝调用，极大地减少了重复上传的带宽浪费，确保了整个团队出品的系列短剧在视觉VI（视觉识别系统）与听觉风格上的高度一致性与工业化标准。")
            ]
        }
    ]

    for section in sections:
        add_heading(section["title"], level=1)
        for sub_title, para in section["content"]:
            add_heading(sub_title, level=2)
            add_para(para)
            # Add a placeholder for screenshots to simulate the manual format
